def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_threat_bid = 0.0
    weak_pressure_bid = 0.0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > 300 and opp.get('hp', 0) > 4:
                    if float(bid) > strong_threat_bid:
                        strong_threat_bid = float(bid)
                else:
                    if float(bid) > weak_pressure_bid:
                        weak_pressure_bid = float(bid)

    if not alive:
        return float(min(budget, 18.0))

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    emergency = hp <= 2 or no_water >= 2
    danger = hp <= 4 or no_water >= 1

    if emergency:
        base = 0.92 * DAILY_SALARY + 18.0 * scarcity
    elif danger:
        base = 0.68 * DAILY_SALARY + 14.0 * scarcity
    else:
        base = 0.42 * DAILY_SALARY + 10.0 * scarcity

    if len(alive) >= 3:
        base += 4.0
    elif len(alive) == 1:
        base -= 5.0

    target = base

    if strong_threat_bid > 0:
        if emergency:
            target = max(target, min(strong_threat_bid + 2.0, 0.95 * DAILY_SALARY + 20.0 * scarcity))
        elif danger and strong_threat_bid <= 95:
            target = max(target, strong_threat_bid + 1.5)
        elif strong_threat_bid < 60:
            target = max(target, strong_threat_bid + 1.0)
    elif weak_pressure_bid > 0:
        if weak_pressure_bid <= 70:
            target = max(target, weak_pressure_bid + 1.5)
        elif emergency:
            target = max(target, weak_pressure_bid + 1.0)

    if budget < DAILY_SALARY * 1.2:
        target = min(target, budget * 0.72)
    elif budget < DAILY_SALARY * 2.0:
        target = min(target, budget * 0.60)

    if day >= 8 and hp > 4 and no_water == 0:
        target *= 0.92

    if target < 0:
        target = 0.0

    bid = min(budget, round(target, 2))
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents alive, bid low but keep survival margin.
    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace.
    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    # Base bid: aim to win when supply is tight; otherwise conserve.
    # With supply in [15,25], the per-day water is enough for 1-2 agents.
    # We assume competition is strongest when supply is near MIN_SUPPLY.
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Tight supply -> higher base bid; abundant -> lower base bid.
    base = DAILY_SALARY * (0.40 + (1.0 - supply_ratio) * 0.25)  # 0.40..0.65

    # Pressure adjustment from yesterday's observed bids.
    # If others were bidding very high, raise slightly; otherwise keep moderate.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        pressure = 0.18
    elif highest_prev_bid >= DAILY_SALARY * 0.60:
        pressure = 0.10
    else:
        pressure = 0.05

    # Urgency from our hp/no_water_days.
    # If we are close to starvation, bid aggressively.
    urgency = 0.0
    if hp <= 2.0:
        urgency = 0.35
    elif hp <= 4.0:
        urgency = 0.20
    elif no_water_days >= 2:
        urgency = 0.18
    elif no_water_days >= 1:
        urgency = 0.08

    # Final target bid.
    target = base * (1.0 + pressure + urgency)

    # Avoid overspending: keep some buffer for future days.
    # If budget is low, cap at a fraction.
    if budget <= DAILY_SALARY * 0.8:
        target = min(target, budget * 0.85)
    else:
        target = min(target, budget * 0.6)

    # If yesterday bids were extremely high, we don't want to match; we exploit by underbidding.
    if highest_prev_bid >= DAILY_SALARY * 1.5:
        target = min(target, DAILY_SALARY * 0.55 + (highest_prev_bid - DAILY_SALARY * 0.55) * 0.25)

    # Ensure non-negative and within budget.
    bid = max(0.0, min(budget, target))

    # Small deterministic tie-breaker by day parity.
    if int(day) % 2 == 1:
        bid = bid * 1.01

    return float(bid)

